import "../src/ERC20.sol";

contract ERC20Test is Test {
    ERC20 token;
    address owner = address(1);
    address receiver = address(2);
    address spender = address(3);

    function setUp() public {
        vm.startPrank(owner);
        token = new ERC20(1000);
        vm.stopPrank();
    }

